-- Transactional cache generations; Redis is never authoritative for visibility.
CREATE TABLE ce_forum_cache_generation (name VARCHAR(80) PRIMARY KEY, generation VARCHAR(32) NOT NULL, scope VARCHAR(12) NOT NULL DEFAULT 'public');
INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_categories',md5(random()::text || clock_timestamp()::text));
INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_boards',md5(random()::text || clock_timestamp()::text));
