INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_polls',md5(random()::text || clock_timestamp()::text));
INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_poll_options',md5(random()::text || clock_timestamp()::text));
INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_poll_votes',md5(random()::text || clock_timestamp()::text));
INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_questions',md5(random()::text || clock_timestamp()::text));
INSERT INTO ce_forum_cache_generation(name,generation) VALUES ('ce_forum_answer_votes',md5(random()::text || clock_timestamp()::text));
CREATE FUNCTION ce_forum_cache_bump() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE ce_forum_cache_generation SET generation=md5(random()::text || clock_timestamp()::text) WHERE name=TG_TABLE_NAME; RETURN NULL; END; $$;
CREATE TRIGGER ce_fc_0 AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON ce_forum_categories FOR EACH STATEMENT EXECUTE FUNCTION ce_forum_cache_bump();
CREATE TRIGGER ce_fc_1 AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON ce_forum_boards FOR EACH STATEMENT EXECUTE FUNCTION ce_forum_cache_bump();
